let dx, dy;
let xoff, yoff;
let ias, ibs;
let ic, id;
var unicoord = [];
let type;
let somethingChanged = true;

//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

function setup() {
  createCanvas(800, 600);
  background(255);

  dy = 4;
  dx = dy * width / height;
  yoff = -dy/2;
  xoff = -dx/2;

  ias = new Array(height);
  ibs = new Array(width);

  for (let y = 0; y < height; y++) {
    ias[y] = yoff + y * dy / height;
  }

  for (let x = 0; x < width; x++) {
    ibs[x] = xoff + x * dx / width;
  }

  unicoord = new Array(width)[height];
  let pixel = 0;
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      unicoord[x][y] = pixel++;
    }
  }

  loadPixels();
}

//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

function draw() {
  if (somethingChanged) {
    somethingChanged = false;

    if      (type == 0) fractal0();
    else if (type == 1) fractal1();
    else if (type == 2) fractal2();
    else if (type == 3) fractal3();
    else if (type == 4) fractal4();
    else if (type == 5) fractal5();
    else if (type == 6) fractal6();
    else if (type == 7) fractal7();

    updatePixels();
  }
}

//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

function mouseMoved() {
  ic = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -2, 2);
  id = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, -2, 2);

  somethingChanged = true;
}

//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

function mousePressed() {
  type = (type + 1) % 8;
  somethingChanged = true;
}








function fractal0() {
  for (let x = 0; x < width; x++) {
    for (let y = 0; y < height; y++) {
      let ia = ias[y];
      let ib = ibs[x];

      let a = ia;
      let b = ib;
      let c = ic;
      let d = id;

      for (let i = 0; i < 8; i++) {
        let ta = c*c+ia;
        let tb = d*d+ib;
        let tc = b/a+ic;
        let td = a/b+id;
        a = ta;
        b = tb;
        c = tc;
        d = td;
      }

      pixels[unicoord[x][y]] = color(abs(a)*64, abs(d)*64, abs(d)*64);
    }
  }
}

